head.script:
// 담당 범위 : pickerType 가이드 전 항목 (con_pickerType / con_calendarValueType 2개, Body Column 1개)
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
//  - 대상 Column 은 가이드 전제대로 inputType="calendar" 만 사용 (calendar 가 아닌 Column 은 구성하지 않음)
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > pickerType]<br/>inputType='calendar' 인 Column 에서 팝업 달력의 상단 연도/월 영역이 렌더링되는 방식을 설정합니다.",
    "validation" : [
        "'selectbox' 설정 시, 팝업 달력 상단에 연도와 월을 선택하는 SelectBox 와 '연도/월' 이동 버튼이 표시됩니다.",
        "미설정 시, 팝업 달력 상단에 연도와 월을 선택하는 SelectBox 와 '연도/월' 이동 버튼이 표시됩니다.",
        "'dynamic' 설정 시, 팝업 달력 상단에 '연도/월'이 표시되는 영역과 '이전/다음' 이동 버튼이 표시됩니다.",
        "'dynamic' 설정 시, '연도/월' 영역을 클릭하면 별도의 선택 화면으로 전환하여 연도와 월을 선택합니다.",
        "pickerType='dynamic' 일때 팝업 달력의 상단 영역을 클릭하면 '월 선택 > 연도 선택 > 연대 선택' 순서로 화면이 전환됩니다.",
        "pickerType='dynamic' 일때 '이전/다음' 이동 버튼은 날짜 선택 화면에서는 1개월씩, 월 선택 화면에서는 1년씩 이동합니다.",
        "calendarValueType='year','yearMonth' 일때도 pickerType 속성은 동작합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_pickerType.setValue("dynamic");
    con_calendarValueType.setValue("yearMonthDate");

    // 달력 아이콘 / 팝업 달력 안을 클릭하면 결과 출력 (페이지 로딩 시 1회만 등록)
    document.addEventListener("click", scwin.onDocumentClick, true);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - pickerType / calendarValueType 은 Body Column(cdate) 에만 설정 (pickerType 미설정은 속성 자체를 넣지 않는다)
//  - Body Column 은 inputType="calendar" + dataType="date" + viewType="icon" (팝업 달력은 달력 아이콘으로 연다)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] date 셀 클릭 -> 입력창 오른쪽 달력 아이콘 클릭 -> 팝업 달력 위쪽 연도/월 영역, 이동 버튼 클릭\n[확인] 팝업이 열리거나 팝업 달력 안을 클릭할 때마다 결과창에 현재 화면과 위쪽 영역 구성이 출력됩니다."', '', 'label1');

    // 조건 설정 (자체 값 select -> getValue)
    let cPickerType = con_pickerType.getValue();
    let cCalendarValueType = con_calendarValueType.getValue();

    // calendarValueType 별 데이터 / 포맷
    let fmt = scwin.formatInfo[cCalendarValueType];

    // dataList 생성 (calendar Column 바인딩 컬럼은 dataType="date")
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cdate" name="cdate" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([{ "cdate" : fmt.data }], false);

    // cdate Column 속성
    let attrCol = ' calendarValueType="' + cCalendarValueType + '" ioFormat="' + fmt.ioFormat + '" displayFormat="' + fmt.displayFormat + '"';
    attrCol += (cPickerType === '') ? '' : ' pickerType="' + cPickerType + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:300px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column1" value="date"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" style="" id="cdate" inputType="calendar" dataType="date" viewType="icon"' + attrCol + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// calendarValueType 별 데이터 / 포맷
scwin.formatInfo = {
    "yearMonthDate" : { "data" : "20261015", "ioFormat" : "yyyyMMdd", "displayFormat" : "yyyy-MM-dd" },
    "yearMonth" : { "data" : "202610", "ioFormat" : "yyyyMM", "displayFormat" : "yyyy-MM" },
    "year" : { "data" : "2026", "ioFormat" : "yyyy", "displayFormat" : "yyyy" }
};



// 화면에 열려 있는 target1 의 팝업 달력 render 반환 (없으면 null)
scwin.getOpenedCalendar = function () {
    if (typeof target1 === 'undefined' || !target1) {
        return null;
    }
    let cals = document.querySelectorAll("div.w2calendar[id*='G_" + target1.id + "__']");
    for (let i = 0; i < cals.length; i++) {
        if (cals[i].offsetWidth > 0 && cals[i].offsetHeight > 0) {
            return cals[i];
        }
    }
    return null;
}



// 달력 아이콘 / 팝업 달력 안 클릭 시 결과 출력
scwin.onDocumentClick = function (e) {
    let elem = e.target;
    if (!elem || !elem.closest || typeof target1 === 'undefined' || !target1) {
        return;
    }
    let btn = elem.closest("button.w2inputCalendar_button");
    let cal = elem.closest("div.w2calendar");
    if ((btn && btn.id.indexOf("G_" + target1.id + "__") >= 0) || (cal && cal.id.indexOf("G_" + target1.id + "__") >= 0)) {
        setTimeout(scwin.printCalendarHeader, 200);
    }
}



// 화면에 보이는 요소인지 확인
scwin.isVisible = function (elem) {
    return !!elem && elem.offsetWidth > 0 && elem.offsetHeight > 0 && getComputedStyle(elem).visibility !== "hidden";
}



// validation 1 ~ 7 판정 출력 : 팝업 달력 위쪽 영역 구성 / 현재 화면
//  - selectbox(미설정) : 연도/월 SelectBox 표시값 + 이동 버튼 목록 (validation 1, 2, 7)
//  - dynamic : 현재 화면(날짜/월/연도/연대 선택) + 연도/월 영역 텍스트 + 이전/다음 버튼 (validation 3 ~ 7)
scwin.printCalendarHeader = function () {
    let cal = scwin.getOpenedCalendar();
    if (!cal) {
        return;
    }
    let bottom = wf_body_bottom.getObj("scwin");
    let entity = cal.querySelector(".w2calendar_picker_header_dynamic_entity");

    if (!scwin.isVisible(entity)) {
        // 연도/월 SelectBox 표시값
        let selects = [];
        [["year", "연도"], ["month", "월"]].forEach(function (info) {
            let sel = cal.querySelector(".w2calendar_selectbox_" + info[0]);
            if (scwin.isVisible(sel)) {
                let lbl = sel.querySelector(".w2selectbox_label");
                selects.push(info[1] + " SelectBox(" + (lbl ? lbl.textContent : "") + ")");
            }
        });
        // 연도/월 이동 버튼 (title)
        let moves = [];
        cal.querySelectorAll(".w2calendar_header [class*='w2calendar_header_last_'], .w2calendar_header [class*='w2calendar_header_next_']").forEach(function (b) {
            if (scwin.isVisible(b)) {
                moves.push(b.title);
            }
        });
        bottom.setReturnValue("위쪽 영역 : " + selects.join(" ") + " / 이동 버튼 : " + moves.join(", "));
        return;
    }

    // dynamic : 현재 화면 구분 (선택 표의 첫 항목 텍스트 : 1월 / 2026 / YYYY - YYYY)
    let screen = "날짜 선택";
    let picker = cal.querySelector(".w2calendar_picker_content");
    if (scwin.isVisible(picker)) {
        let first = picker.querySelector(".w2calendar_picker_cell");
        let text = first ? first.textContent.trim() : "";
        if (/^\d{4}\s*-\s*\d{4}$/.test(text)) {
            screen = "연대 선택";
        } else if (/^\d{4}$/.test(text)) {
            screen = "연도 선택";
        } else {
            screen = "월 선택";
        }
    }
    let spans = entity.querySelectorAll("span");
    let headerText = spans.length ? Array.prototype.map.call(spans, function (sp) { return sp.textContent; }).join(" ") : entity.textContent;
    let prevBtn = scwin.isVisible(cal.querySelector(".w2calendar_picker_header_last_entity"));
    let nextBtn = scwin.isVisible(cal.querySelector(".w2calendar_picker_header_next_entity"));
    bottom.setReturnValue("화면 : " + screen + " / 연도/월 영역 : " + headerText + " / 이전 버튼 : " + (prevBtn ? "표시" : "미표시") + ", 다음 버튼 : " + (nextBtn ? "표시" : "미표시"));
}
